<template>
  <AppLayout>
    <div class="space-y-4">
      <section class="card p-2">
        <div class="flex flex-wrap gap-2" role="tablist" :aria-label="t('invoice.adminViews')">
          <button class="btn inline-flex items-center gap-2" :class="activeTab === 'applications' ? 'btn-primary' : 'btn-ghost'" role="tab" :aria-selected="activeTab === 'applications'" @click="switchTab('applications')"><Icon name="document" size="sm" />{{ t('invoice.applications') }}</button>
          <button class="btn inline-flex items-center gap-2" :class="activeTab === 'historical' ? 'btn-primary' : 'btn-ghost'" role="tab" :aria-selected="activeTab === 'historical'" @click="switchTab('historical')"><Icon name="clipboard" size="sm" />{{ t('invoice.historicalRecords') }}</button>
        </div>
      </section>

      <template v-if="activeTab === 'applications'">
        <section class="card p-4"><div class="flex flex-wrap items-center gap-3"><input v-model="applicationKeyword" class="input min-w-56 flex-1" :placeholder="t('invoice.applicationNo')" @keyup.enter="loadApplications" /><Select v-model="applicationStatus" :options="applicationStatusOptions" class="w-36" @change="loadApplications" /><button class="btn btn-secondary" :disabled="applicationLoading" :title="t('common.refresh')" @click="loadApplications"><Icon name="refresh" size="md" :class="applicationLoading ? 'animate-spin' : ''" /></button></div></section>
        <section class="card overflow-hidden"><div class="border-b border-gray-200 px-4 py-4 dark:border-dark-700 sm:px-5"><h2 class="text-lg font-semibold text-gray-900 dark:text-white">{{ t('invoice.applications') }}</h2></div><div class="overflow-x-auto"><table class="w-full min-w-[820px] divide-y divide-gray-200 dark:divide-dark-700"><thead class="bg-gray-50 dark:bg-dark-800"><tr><th class="px-4 py-3 text-left text-xs font-medium uppercase tracking-wider text-gray-500">{{ t('invoice.applicationNo') }}</th><th class="px-4 py-3 text-left text-xs font-medium uppercase tracking-wider text-gray-500">{{ t('common.email') }}</th><th class="px-4 py-3 text-right text-xs font-medium uppercase tracking-wider text-gray-500">{{ t('invoice.totalSelected') }}</th><th class="px-4 py-3 text-right text-xs font-medium uppercase tracking-wider text-gray-500">{{ t('invoice.status') }}</th><th class="px-4 py-3 text-right text-xs font-medium uppercase tracking-wider text-gray-500">{{ t('invoice.date') }}</th><th class="w-24 px-4 py-3"></th></tr></thead><tbody class="divide-y divide-gray-200 bg-white dark:divide-dark-700 dark:bg-dark-900"><tr v-if="applicationLoading"><td colspan="6" class="px-4 py-12 text-center text-sm text-gray-500">{{ t('common.loading') }}</td></tr><tr v-else-if="applications.length === 0"><td colspan="6" class="px-4 py-12 text-center text-sm text-gray-500">{{ t('invoice.noRecords') }}</td></tr><tr v-for="application in applications" v-else :key="application.id" class="hover:bg-gray-50 dark:hover:bg-dark-800"><td class="px-4 py-3 font-mono text-sm text-gray-900 dark:text-gray-100">{{ application.application_no }}</td><td class="px-4 py-3 text-sm text-gray-700 dark:text-gray-300">{{ application.user_email || `#${application.user_id}` }}</td><td class="px-4 py-3 text-right text-sm font-medium text-gray-900 dark:text-gray-100">{{ application.total_amount.toFixed(2) }}</td><td class="px-4 py-3 text-right text-sm" :class="statusClass(application.status)">{{ statusLabel(application.status) }}</td><td class="px-4 py-3 text-right text-sm text-gray-500 dark:text-gray-400">{{ formatDate(application.created_at) }}</td><td class="px-4 py-3 text-right"><button class="btn btn-ghost btn-sm inline-flex items-center gap-1" @click="openDetail(application.id)"><Icon name="eye" size="sm" />{{ t('common.view') }}</button></td></tr></tbody></table></div><Pagination v-if="applicationPagination.total > 0" :page="applicationPagination.page" :total="applicationPagination.total" :page-size="applicationPagination.page_size" @update:page="changeApplicationPage" @update:pageSize="changeApplicationPageSize" /></section>
      </template>

      <template v-else>
        <section class="card p-4"><div class="grid gap-3 md:grid-cols-[9rem_minmax(12rem,1fr)_minmax(14rem,1fr)_9rem_auto]"><input v-model="historicalUserID" class="input" inputmode="numeric" :placeholder="t('invoice.userId')" @keyup.enter="loadHistoricalRecords" /><input v-model="historicalKeyword" class="input" :placeholder="t('invoice.historicalSearch')" @keyup.enter="loadHistoricalRecords" /><Select v-model="historicalStatus" :options="historicalStatusOptions" @change="loadHistoricalRecords" /><button class="btn btn-secondary inline-flex items-center justify-center gap-2" :disabled="historicalLoading" @click="loadHistoricalRecords"><Icon name="refresh" size="sm" :class="historicalLoading ? 'animate-spin' : ''" />{{ t('common.refresh') }}</button></div></section>
        <section class="card overflow-hidden"><div class="flex flex-wrap items-center justify-between gap-3 border-b border-gray-200 px-4 py-4 dark:border-dark-700 sm:px-5"><div><h2 class="text-lg font-semibold text-gray-900 dark:text-white">{{ t('invoice.historicalRecords') }}</h2><p class="mt-1 text-sm text-gray-500 dark:text-gray-400">{{ t('invoice.historicalDescription') }}</p></div><div class="flex items-center gap-4 text-sm"><span class="text-gray-500 dark:text-gray-400">{{ t('invoice.selectedCount', { count: selectedHistoricalRecords.length }) }}</span><span class="font-semibold text-primary-600 dark:text-primary-400">{{ t('invoice.totalSelected') }}: {{ historicalSelectedTotal.toFixed(2) }}</span><button class="btn btn-primary inline-flex items-center gap-2" :disabled="historicalSubmitting || selectedHistoricalRecords.length === 0" @click="openHistoricalConfirm"><Icon name="check" size="sm" />{{ historicalSubmitting ? t('common.processing') : t('invoice.historicalMark') }}</button></div></div><div class="overflow-x-auto"><table class="w-full min-w-[1080px] divide-y divide-gray-200 dark:divide-dark-700"><thead class="bg-gray-50 dark:bg-dark-800"><tr><th class="w-12 px-4 py-3 text-center"><input type="checkbox" class="h-4 w-4 rounded border-gray-300 text-primary-600 focus:ring-primary-500" :checked="allHistoricalSelectableSelected" :disabled="historicalSelectableRecords.length === 0" @change="toggleHistoricalAll(($event.target as HTMLInputElement).checked)" /></th><th class="px-4 py-3 text-left text-xs font-medium uppercase tracking-wider text-gray-500">{{ t('invoice.user') }}</th><th class="px-4 py-3 text-left text-xs font-medium uppercase tracking-wider text-gray-500">{{ t('invoice.source') }}</th><th class="px-4 py-3 text-left text-xs font-medium uppercase tracking-wider text-gray-500">{{ t('invoice.sourceReference') }}</th><th class="px-4 py-3 text-right text-xs font-medium uppercase tracking-wider text-gray-500">{{ t('invoice.amount') }}</th><th class="px-4 py-3 text-right text-xs font-medium uppercase tracking-wider text-gray-500">{{ t('invoice.date') }}</th><th class="px-4 py-3 text-right text-xs font-medium uppercase tracking-wider text-gray-500">{{ t('invoice.status') }}</th><th class="px-4 py-3 text-right text-xs font-medium uppercase tracking-wider text-gray-500">{{ t('invoice.markedAt') }}</th><th class="px-4 py-3 text-left text-xs font-medium uppercase tracking-wider text-gray-500">{{ t('invoice.markedBy') }}</th></tr></thead><tbody class="divide-y divide-gray-200 dark:divide-dark-700 dark:bg-dark-900"><tr v-if="historicalLoading"><td colspan="9" class="px-4 py-12 text-center text-sm text-gray-500">{{ t('common.loading') }}</td></tr><tr v-else-if="historicalRecords.length === 0"><td colspan="9" class="px-4 py-12 text-center text-sm text-gray-500">{{ t('invoice.noRecords') }}</td></tr><tr v-for="record in historicalRecords" v-else :key="recordKey(record)" :class="record.selectable ? 'hover:bg-gray-50 dark:hover:bg-dark-800' : 'bg-gray-50/60 dark:bg-dark-800/40'"><td class="px-4 py-3 text-center"><input type="checkbox" class="h-4 w-4 rounded border-gray-300 text-primary-600 focus:ring-primary-500 disabled:cursor-not-allowed disabled:opacity-40" :checked="isHistoricalSelected(record)" :disabled="!record.selectable" @change="toggleHistoricalRecord(record, ($event.target as HTMLInputElement).checked)" /></td><td class="px-4 py-3 text-sm text-gray-700 dark:text-gray-300"><div class="font-medium">{{ record.user_name || record.user_email || `#${record.user_id}` }}</div><div class="text-xs text-gray-500">#{{ record.user_id }}<span v-if="record.user_email && record.user_name"> · {{ record.user_email }}</span></div></td><td class="px-4 py-3 text-sm text-gray-700 dark:text-gray-300">{{ sourceLabel(record.source_type) }}</td><td class="px-4 py-3 font-mono text-sm text-gray-700 dark:text-gray-300">{{ record.source_reference }}</td><td class="px-4 py-3 text-right text-sm font-medium text-gray-900 dark:text-gray-100">{{ record.amount.toFixed(2) }}</td><td class="px-4 py-3 text-right text-sm text-gray-500 dark:text-gray-400">{{ formatDate(record.occurred_at) }}</td><td class="px-4 py-3 text-right text-sm" :class="recordStatusClass(record)">{{ recordStatusLabel(record) }}</td><td class="px-4 py-3 text-right text-sm text-gray-500 dark:text-gray-400">{{ formatDate(record.marked_at) }}</td><td class="px-4 py-3 text-sm text-gray-600 dark:text-gray-300">{{ record.marked_by_email || (record.marked_by ? `#${record.marked_by}` : '-') }}</td></tr></tbody></table></div><Pagination v-if="historicalPagination.total > 0" :page="historicalPagination.page" :total="historicalPagination.total" :page-size="historicalPagination.page_size" @update:page="changeHistoricalPage" @update:pageSize="changeHistoricalPageSize" /></section>
      </template>
    </div>

    <BaseDialog :show="!!detail" :title="t('invoice.detail')" width="wide" @close="detail = null"><div v-if="detail" class="space-y-5"><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><div><p class="input-label">{{ t('invoice.applicationNo') }}</p><p class="font-mono text-sm text-gray-900 dark:text-gray-100">{{ detail.application_no }}</p></div><div><p class="input-label">{{ t('common.email') }}</p><p class="text-sm text-gray-900 dark:text-gray-100">{{ detail.user_email || `#${detail.user_id}` }}</p></div><div><p class="input-label">{{ t('invoice.status') }}</p><p :class="['text-sm font-medium', statusClass(detail.status)]">{{ statusLabel(detail.status) }}</p></div><div><p class="input-label">{{ t('invoice.date') }}</p><p class="text-sm text-gray-900 dark:text-gray-100">{{ formatDate(detail.created_at) }}</p></div><div><p class="input-label">{{ t('invoice.email') }}</p><p class="break-all text-sm text-gray-900 dark:text-gray-100">{{ detail.email }}</p></div><div><p class="input-label">{{ t('invoice.taxNumber') }}</p><p class="break-all text-sm text-gray-900 dark:text-gray-100">{{ detail.tax_number }}</p></div><div><p class="input-label">{{ t('invoice.companyName') }}</p><p class="break-all text-sm text-gray-900 dark:text-gray-100">{{ detail.company_name }}</p></div><div><p class="input-label">{{ t('invoice.totalSelected') }}</p><p class="text-sm font-semibold text-primary-600 dark:text-primary-400">{{ detail.total_amount.toFixed(2) }}</p></div></div><div><h3 class="mb-2 text-sm font-semibold text-gray-900 dark:text-white">{{ t('invoice.records') }}</h3><div class="overflow-x-auto rounded-lg border border-gray-200 dark:border-dark-700"><table class="w-full min-w-[560px] divide-y divide-gray-200 dark:divide-dark-700"><thead class="bg-gray-50 dark:bg-dark-800"><tr><th class="px-3 py-2 text-left text-xs font-medium text-gray-500">{{ t('invoice.source') }}</th><th class="px-3 py-2 text-left text-xs font-medium text-gray-500">{{ t('invoice.applicationNo') }}</th><th class="px-3 py-2 text-right text-xs font-medium text-gray-500">{{ t('invoice.amount') }}</th></tr></thead><tbody class="divide-y divide-gray-200 dark:divide-dark-700"><tr v-for="item in detail.items || []" :key="`${item.source_type}:${item.source_id}`"><td class="px-3 py-2 text-sm text-gray-700 dark:text-gray-300">{{ sourceLabel(item.source_type) }}</td><td class="px-3 py-2 font-mono text-sm text-gray-700 dark:text-gray-300">{{ item.source_reference }}</td><td class="px-3 py-2 text-right text-sm text-gray-900 dark:text-gray-100">{{ item.amount.toFixed(2) }}</td></tr></tbody></table></div></div><p v-if="detail.status === 'REJECTED' && detail.rejection_reason" class="rounded-lg bg-red-50 p-3 text-sm text-red-700 dark:bg-red-900/20 dark:text-red-300">{{ t('invoice.rejectReason') }}：{{ detail.rejection_reason }}</p></div><template #footer><div class="flex justify-end gap-3"><button class="btn btn-secondary" @click="detail = null">{{ t('common.close') }}</button><template v-if="detail?.status === 'PENDING'"><button class="btn btn-danger" :disabled="actionLoading" @click="openReject">{{ t('invoice.reject') }}</button><button class="btn btn-primary" :disabled="actionLoading" @click="confirmComplete">{{ actionLoading ? t('common.processing') : t('invoice.complete') }}</button></template></div></template></BaseDialog>
    <BaseDialog :show="showReject" :title="t('invoice.reject')" width="normal" @close="showReject = false"><label><span class="input-label">{{ t('invoice.rejectReason') }}</span><textarea v-model.trim="rejectReason" rows="4" class="input mt-1 w-full" /></label><template #footer><div class="flex justify-end gap-3"><button class="btn btn-secondary" @click="showReject = false">{{ t('common.cancel') }}</button><button class="btn btn-danger" :disabled="actionLoading || !rejectReason" @click="confirmReject">{{ actionLoading ? t('common.processing') : t('invoice.reject') }}</button></div></template></BaseDialog>
    <BaseDialog :show="showHistoricalConfirm" :title="t('invoice.historicalMarkTitle')" width="normal" @close="showHistoricalConfirm = false"><div class="space-y-3 text-sm text-gray-700 dark:text-gray-300"><p>{{ t('invoice.historicalMarkMessage') }}</p><dl class="grid grid-cols-[auto_1fr] gap-x-4 gap-y-2 rounded-lg bg-gray-50 p-4 dark:bg-dark-800"><dt class="text-gray-500 dark:text-gray-400">{{ t('invoice.selectedCount', { count: selectedHistoricalRecords.length }) }}</dt><dd class="text-right font-medium">{{ historicalSelectedTotal.toFixed(2) }}</dd><dt class="text-gray-500 dark:text-gray-400">{{ t('invoice.status') }}</dt><dd class="text-right">{{ t('invoice.historicalCompleted') }}</dd></dl></div><template #footer><div class="flex justify-end gap-3"><button class="btn btn-secondary" @click="showHistoricalConfirm = false">{{ t('common.cancel') }}</button><button class="btn btn-danger" :disabled="historicalSubmitting" @click="confirmHistoricalMark">{{ historicalSubmitting ? t('common.processing') : t('invoice.historicalMarkConfirm') }}</button></div></template></BaseDialog>
  </AppLayout>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { adminInvoiceAPI, type AdminInvoiceRecord } from '@/api/admin/invoices'
import type { InvoiceApplication } from '@/api/payment'
import { useAppStore } from '@/stores'
import { extractI18nErrorMessage } from '@/utils/apiError'
import AppLayout from '@/components/layout/AppLayout.vue'
import BaseDialog from '@/components/common/BaseDialog.vue'
import Pagination from '@/components/common/Pagination.vue'
import Select from '@/components/common/Select.vue'
import Icon from '@/components/icons/Icon.vue'

const { t } = useI18n(); const appStore = useAppStore()
const activeTab = ref<'applications' | 'historical'>('applications')
const applications = ref<InvoiceApplication[]>([]); const applicationLoading = ref(false); const applicationKeyword = ref(''); const applicationStatus = ref(''); const applicationPagination = reactive({ page: 1, page_size: 20, total: 0 })
const detail = ref<InvoiceApplication | null>(null); const actionLoading = ref(false); const showReject = ref(false); const rejectReason = ref('')
const historicalRecords = ref<AdminInvoiceRecord[]>([]); const historicalLoading = ref(false); const historicalSubmitting = ref(false); const historicalKeyword = ref(''); const historicalUserID = ref(''); const historicalStatus = ref('all'); const historicalPagination = reactive({ page: 1, page_size: 20, total: 0 }); const selectedHistoricalMap = reactive<Record<string, AdminInvoiceRecord>>({}); const showHistoricalConfirm = ref(false)
const applicationStatusOptions = computed(() => [{ value: '', label: t('common.all') }, { value: 'PENDING', label: t('invoice.pending') }, { value: 'COMPLETED', label: t('invoice.completed') }, { value: 'REJECTED', label: t('invoice.rejected') }])
const historicalStatusOptions = computed(() => [{ value: 'all', label: t('common.all') }, { value: 'available', label: t('invoice.available') }, { value: 'applied', label: t('invoice.applied') }, { value: 'historical_completed', label: t('invoice.historicalCompleted') }])
const historicalSelectableRecords = computed(() => historicalRecords.value.filter((record) => record.selectable)); const selectedHistoricalRecords = computed(() => Object.values(selectedHistoricalMap)); const historicalSelectedTotal = computed(() => selectedHistoricalRecords.value.reduce((sum, record) => sum + record.amount, 0)); const allHistoricalSelectableSelected = computed(() => historicalSelectableRecords.value.length > 0 && historicalSelectableRecords.value.every((record) => isHistoricalSelected(record)))
function statusLabel(value: string) { return value === 'PENDING' ? t('invoice.pending') : value === 'COMPLETED' ? t('invoice.completed') : value === 'REJECTED' ? t('invoice.rejected') : value } function statusClass(value: string) { return value === 'COMPLETED' ? 'text-emerald-600 dark:text-emerald-400' : value === 'REJECTED' ? 'text-red-600 dark:text-red-400' : 'text-amber-600 dark:text-amber-400' } function recordStatusLabel(record: AdminInvoiceRecord) { return record.application_status === 'HISTORICAL_COMPLETED' ? t('invoice.historicalCompleted') : record.application_status ? t('invoice.applied') : t('invoice.available') } function recordStatusClass(record: AdminInvoiceRecord) { return record.application_status === 'HISTORICAL_COMPLETED' ? 'text-sky-600 dark:text-sky-400' : record.application_status ? 'text-amber-600 dark:text-amber-400' : 'text-emerald-600 dark:text-emerald-400' } function sourceLabel(type: string) { return t(`invoice.source${type === 'payment_order' ? 'Payment' : type === 'redeem_code' ? 'Redeem' : type === 'admin_grant' ? 'Grant' : 'Affiliate'}`) } function formatDate(value?: string) { return value ? new Date(value).toLocaleString() : '-' } function recordKey(record: AdminInvoiceRecord) { return `${record.source_type}:${record.source_id}` } function isHistoricalSelected(record: AdminInvoiceRecord) { return !!selectedHistoricalMap[recordKey(record)] } function toggleHistoricalRecord(record: AdminInvoiceRecord, checked: boolean) { const key = recordKey(record); if (checked && record.selectable) selectedHistoricalMap[key] = record; else delete selectedHistoricalMap[key] } function toggleHistoricalAll(checked: boolean) { historicalSelectableRecords.value.forEach((record) => toggleHistoricalRecord(record, checked)) } function switchTab(tab: 'applications' | 'historical') { activeTab.value = tab; if (tab === 'historical' && historicalRecords.value.length === 0) loadHistoricalRecords() }
async function loadApplications() { applicationLoading.value = true; try { const response = await adminInvoiceAPI.getApplications({ page: applicationPagination.page, page_size: applicationPagination.page_size, status: applicationStatus.value || undefined, keyword: applicationKeyword.value.trim() || undefined }); applications.value = response.data.items || []; applicationPagination.total = response.data.total || 0 } catch (error: unknown) { appStore.showError(extractI18nErrorMessage(error, t, 'invoice.errors', t('invoice.errors.load'))) } finally { applicationLoading.value = false } }
async function loadHistoricalRecords() { historicalLoading.value = true; try { const parsedUserID = Number.parseInt(historicalUserID.value.trim(), 10); const response = await adminInvoiceAPI.getRecords({ page: historicalPagination.page, page_size: historicalPagination.page_size, user_id: Number.isFinite(parsedUserID) && parsedUserID > 0 ? parsedUserID : undefined, keyword: historicalKeyword.value.trim() || undefined, invoice_status: historicalStatus.value }); historicalRecords.value = response.data.items || []; historicalPagination.total = response.data.total || 0; historicalRecords.value.forEach((record) => { if (!record.selectable) delete selectedHistoricalMap[recordKey(record)] }) } catch (error: unknown) { appStore.showError(extractI18nErrorMessage(error, t, 'invoice.errors', t('invoice.errors.load'))) } finally { historicalLoading.value = false } }
function changeApplicationPage(page: number) { applicationPagination.page = page; loadApplications() } function changeApplicationPageSize(size: number) { applicationPagination.page_size = size; applicationPagination.page = 1; loadApplications() } function changeHistoricalPage(page: number) { historicalPagination.page = page; loadHistoricalRecords() } function changeHistoricalPageSize(size: number) { historicalPagination.page_size = size; historicalPagination.page = 1; loadHistoricalRecords() } async function openDetail(id: number) { try { const response = await adminInvoiceAPI.getApplication(id); detail.value = response.data } catch (error: unknown) { appStore.showError(extractI18nErrorMessage(error, t, 'invoice.errors', t('invoice.errors.load'))) } } async function confirmComplete() { if (!detail.value || !window.confirm(t('invoice.confirmComplete'))) return; actionLoading.value = true; try { await adminInvoiceAPI.completeApplication(detail.value.id); appStore.showSuccess(t('common.success')); detail.value = null; await loadApplications() } catch (error: unknown) { appStore.showError(extractI18nErrorMessage(error, t, 'invoice.errors', t('common.error'))) } finally { actionLoading.value = false } } function openReject() { rejectReason.value = ''; showReject.value = true } async function confirmReject() { if (!detail.value || !rejectReason.value) return; actionLoading.value = true; try { await adminInvoiceAPI.rejectApplication(detail.value.id, rejectReason.value); showReject.value = false; detail.value = null; appStore.showSuccess(t('common.success')); await loadApplications() } catch (error: unknown) { appStore.showError(extractI18nErrorMessage(error, t, 'invoice.errors', t('common.error'))) } finally { actionLoading.value = false } }
function openHistoricalConfirm() { if (selectedHistoricalRecords.value.length > 0) showHistoricalConfirm.value = true } async function confirmHistoricalMark() { if (selectedHistoricalRecords.value.length === 0) return; historicalSubmitting.value = true; try { await adminInvoiceAPI.markHistoricalRecords(selectedHistoricalRecords.value.map((record) => ({ source_type: record.source_type, source_id: record.source_id }))); showHistoricalConfirm.value = false; Object.keys(selectedHistoricalMap).forEach((key) => delete selectedHistoricalMap[key]); appStore.showSuccess(t('common.success')); await loadHistoricalRecords() } catch (error: unknown) { appStore.showError(extractI18nErrorMessage(error, t, 'invoice.errors', t('invoice.errors.historicalMark'))) } finally { historicalSubmitting.value = false } }
onMounted(loadApplications)
</script>
